// Letterheads for the delivery note, chosen by the session's country: the
// Italian warehouse issues DDTs as SIMICO, the French and German ones as
// Ecom Prep Hub. Embedded as data URLs so the PDF is built the same way
// offline, with nothing to fetch at the loading bay.

const SIMICO = 'data:image/jpeg;base64,';
const ECOM_PREP = 'data:image/jpeg;base64,';

const BY_COUNTRY = { IT: SIMICO, FR: ECOM_PREP, DE: ECOM_PREP };

export function ddtLogoForCountry(country) {
  return BY_COUNTRY[String(country || '').toUpperCase()] || null;
}
